Definition aobj (a n : Z) : Prop := a mod 4096 = 0 /\ 4096 <= a /\ a + n <= ATOP /\ sclr a n /\ iclr a n.
Lemma aobj_img : forall a n, aobj a n -> 0x10000 <= n -> AIMG_HI <= a.
Proof. intros a n (_ & H1 & _ & _ & H4) Hn. unfold iclr, AIMG_LO, AIMG_HI in *. lia. Qed.

